<script setup lang="ts">
import {usePayrollText} from '../payrollText'
import type {PayItem} from '../payrollTypes'
const props=defineProps<{items:PayItem[];disabled?:boolean;recurring?:boolean}>(),{r}=usePayrollText()
function changeKind(item:PayItem){if(props.recurring&&['ow_allowance','ow_additional','ow_accommodation'].includes(item.kind))item.proration='full';else delete item.proration}
function add(){if(props.items.length<20)props.items.push({label:'',kind:'ow_allowance',amount:'',...(props.recurring?{proration:'full' as const}:{})})}
</script>
<template><div class="wf-pay-items"><p class="wf-hint">{{r('itemHint')}}</p><article v-for="(item,index) in items" :key="index" class="wf-pay-item"><div class="wf-grid"><label>{{r('itemLabel')}}<input v-model="item.label" required maxlength="100" :disabled="disabled"></label><label>{{r('kind')}}<select v-model="item.kind" @change="changeKind(item)" :disabled="disabled"><option value="ow_additional">{{r('ow_additional')}}</option><option value="ow_accommodation">{{r('ow_accommodation')}}</option><option value="cdac">{{r('cdacManualItem')}}</option><option value="ow_allowance">{{r('ow_allowance')}}</option><option value="reimbursement">{{r('reimbursement')}}</option><option value="deduction">{{r('deduction')}}</option><option value="employer_charge">{{r('employer_charge')}}</option></select></label></div><div class="wf-inline"><label>{{r('amount')}}<input v-model="item.amount" required inputmode="decimal" pattern="\d{1,9}(\.\d{1,2})?" :disabled="disabled"></label><button type="button" :disabled="disabled" @click="items.splice(index,1)">{{r('remove')}}</button></div><label v-if="recurring&&['ow_allowance','ow_additional','ow_accommodation'].includes(item.kind)">{{r('proration')}}<select v-model="item.proration" :disabled="disabled"><option :value="undefined">{{r('prorationLegacy')}}</option><option value="full">{{r('prorationFull')}}</option><option value="payable">{{r('prorationPayable')}}</option></select></label></article><button type="button" :disabled="disabled||items.length>=20" @click="add">{{r('addItem')}}</button></div></template>
